package com.acme.member.renewal;

import java.time.LocalDateTime;
import java.util.Objects;
import java.util.UUID;

/** 续费订单。externalTxnId 是支付平台流水号，要求全局唯一（幂等依据）。 */
public class RenewalOrder {

    public enum Status {
        PAID,
        FAILED
    }

    private final String id;
    private final String memberId;
    private final String externalTxnId;
    private final int months;
    private final long amountCents;
    private final Status status;
    private final LocalDateTime paidAt;
    private final String couponCode;
    private final double discountRate;
    private final long originalAmountCents;

    /** 无券订单：实付等于原价，折扣率为 1.0，券码为空。 */
    public RenewalOrder(String memberId, String externalTxnId, int months, long amountCents, LocalDateTime paidAt) {
        this(memberId, externalTxnId, months, amountCents, paidAt, null, 1.0, amountCents);
    }

    /** 完整订单：amountCents 为实付，originalAmountCents 为原价。 */
    public RenewalOrder(String memberId, String externalTxnId, int months, long amountCents, LocalDateTime paidAt,
                        String couponCode, double discountRate, long originalAmountCents) {
        this.id = UUID.randomUUID().toString();
        this.memberId = Objects.requireNonNull(memberId);
        this.externalTxnId = Objects.requireNonNull(externalTxnId);
        this.months = months;
        this.amountCents = amountCents;
        this.status = Status.PAID;
        this.paidAt = Objects.requireNonNull(paidAt);
        this.couponCode = couponCode;
        this.discountRate = discountRate;
        this.originalAmountCents = originalAmountCents;
    }

    public String getId() {
        return id;
    }

    public String getMemberId() {
        return memberId;
    }

    public String getExternalTxnId() {
        return externalTxnId;
    }

    public int getMonths() {
        return months;
    }

    /** 实付金额（分）。 */
    public long getAmountCents() {
        return amountCents;
    }

    public Status getStatus() {
        return status;
    }

    public LocalDateTime getPaidAt() {
        return paidAt;
    }

    /** 使用的券码；无券为 null。 */
    public String getCouponCode() {
        return couponCode;
    }

    /** 折扣率；无券为 1.0。 */
    public double getDiscountRate() {
        return discountRate;
    }

    /** 原价（分）；无券时等于实付。 */
    public long getOriginalAmountCents() {
        return originalAmountCents;
    }
}

