import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Clock;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Optional;

/**
 * 续费回调处理。
 *
 * <p>规则：验签失败拒绝；同一支付流水号只处理一次（幂等）；处理成功只顺延一次到期日。
 * 带券回调以 {@code amountCents} 为原价，按券折扣算出实付后按实付验签；
 * 无券回调完全沿用原有语义。
 */
@Service
public class RenewalService {

    static final String COUPON_NOT_FOUND = "COUPON_NOT_FOUND";
    static final String COUPON_DISABLED = "COUPON_DISABLED";
    static final String COUPON_EXPIRED = "COUPON_EXPIRED";
    static final String COUPON_ALREADY_USED = "COUPON_ALREADY_USED";
    static final String INVALID_AMOUNT = "INVALID_AMOUNT";

    private final RenewalRepository renewalRepository;
    private final MemberService memberService;
    private final CouponRepository couponRepository;
    private final SignatureVerifier signatureVerifier;
    private final Clock clock;
    private final ZoneId zoneId;
    private final Object couponLock = new Object();

    @Autowired
    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          CouponRepository couponRepository,
                          SignatureVerifier signatureVerifier,
                          Clock clock,
                          @Value("${renewal.timezone:Asia/Shanghai}") String zoneId) {
        this(renewalRepository, memberService, couponRepository, signatureVerifier, clock, ZoneId.of(zoneId));
    }

    /** 兼容既有调用方（无券场景），内部使用独立的空券仓储。 */
    RenewalService(RenewalRepository renewalRepository,
                   MemberService memberService,
                   SignatureVerifier signatureVerifier,
                   Clock clock,
                   ZoneId zoneId) {
        this(renewalRepository, memberService, new CouponRepository(), signatureVerifier, clock, zoneId);
    }

    RenewalService(RenewalRepository renewalRepository,
                   MemberService memberService,
                   CouponRepository couponRepository,
                   SignatureVerifier signatureVerifier,
                   Clock clock,
                   ZoneId zoneId) {
        this.renewalRepository = renewalRepository;
        this.memberService = memberService;
        this.couponRepository = couponRepository;
        this.signatureVerifier = signatureVerifier;
        this.clock = clock;
        this.zoneId = zoneId;
    }

    public CallbackResult handleCallback(CallbackCommand command) {
        String couponCode = normalizeCouponCode(command.couponCode());
        if (couponCode == null) {
            return handleWithoutCoupon(command);
        }
        return handleWithCoupon(command, couponCode);
    }

    /** 无券路径：与改造前完全一致。 */
    private CallbackResult handleWithoutCoupon(CallbackCommand command) {
        verifySignature(command.externalTxnId(), command.amountCents(), command.signature());
        // 幂等：同一流水号直接返回已处理，不再顺延到期日。
        return renewalRepository.findByExternalTxnId(command.externalTxnId())
                .map(existing -> new CallbackResult(true, existing))
                .orElseGet(() -> process(command));
    }

    /** 带券路径：幂等查 → 券校验 → 算实付 → 按实付验签 → 会员 → 落库 → 顺延。 */
    private CallbackResult handleWithCoupon(CallbackCommand command, String couponCode) {
        synchronized (couponLock) {
            Optional<RenewalOrder> existing = renewalRepository.findByExternalTxnId(command.externalTxnId());
            if (existing.isPresent()) {
                verifySignature(command.externalTxnId(), existing.get().getAmountCents(), command.signature());
                return new CallbackResult(true, existing.get());
            }
            Coupon coupon = couponRepository.findByCode(couponCode)
                    .orElseThrow(() -> new CouponException(COUPON_NOT_FOUND));
            LocalDateTime now = LocalDateTime.now(clock.withZone(zoneId));
            if (!coupon.isActive()) {
                throw new CouponException(COUPON_DISABLED);
            }
            if (coupon.isExpired(now)) {
                throw new CouponException(COUPON_EXPIRED);
            }
            if (coupon.isUsed()) {
                throw new CouponException(COUPON_ALREADY_USED);
            }
            if (command.amountCents() <= 0) {
                throw new CouponException(INVALID_AMOUNT);
            }
            long payableCents = payableCents(command.amountCents(), coupon.getDiscountRate());
            verifySignature(command.externalTxnId(), payableCents, command.signature());
            memberService.getMember(command.memberId());
            RenewalOrder order = new RenewalOrder(
                    command.memberId(),
                    command.externalTxnId(),
                    command.months(),
                    payableCents,
                    now,
                    couponCode,
                    coupon.getDiscountRate(),
                    command.amountCents()
            );
            renewalRepository.save(order);
            memberService.renew(command.memberId(), command.months());
            return new CallbackResult(false, order);
        }
    }

    private CallbackResult process(CallbackCommand command) {
        memberService.getMember(command.memberId());
        RenewalOrder order = new RenewalOrder(
                command.memberId(),
                command.externalTxnId(),
                command.months(),
                command.amountCents(),
                LocalDateTime.now(clock.withZone(zoneId))
        );
        renewalRepository.save(order);
        memberService.renew(command.memberId(), command.months());
        return new CallbackResult(false, order);
    }

    private void verifySignature(String externalTxnId, long amountCents, String signature) {
        if (!signatureVerifier.verify(externalTxnId, amountCents, signature)) {
            throw new InvalidSignatureException();
        }
    }

    private static long payableCents(long originalAmountCents, double discountRate) {
        return BigDecimal.valueOf(originalAmountCents)
                .multiply(BigDecimal.valueOf(discountRate))
                .setScale(0, RoundingMode.HALF_UP)
                .longValueExact();
    }

    private static String normalizeCouponCode(String couponCode) {
        return couponCode == null || couponCode.isBlank() ? null : couponCode;
    }

    public boolean verifySignature(String externalTxnId, long amountCents, String signature) {
        return signatureVerifier.verify(externalTxnId, amountCents, signature);
    }

    /** 回调命令；5 参构造等价于不带券。 */
    public record CallbackCommand(String externalTxnId, String memberId, int months, long amountCents,
                                  String signature, String couponCode) {

        public CallbackCommand(String externalTxnId, String memberId, int months, long amountCents, String signature) {
            this(externalTxnId, memberId, months, amountCents, signature, null);
        }
    }

    /** 处理结果：duplicate 表示命中幂等。 */
    public record CallbackResult(boolean duplicate, RenewalOrder order) {
    }

    public static class InvalidSignatureException extends RuntimeException {
        public InvalidSignatureException() {
            super("回调签名校验失败");
        }
    }

    /** 带券回调的业务错误；T3 仅区分业务码，HTTP 状态由控制器统一映射。 */
    public static class CouponException extends RuntimeException {

        private final String code;

