package com.acme.member.renewal;

import com.acme.member.member.Member;
import com.acme.member.member.MemberRepository;
import com.acme.member.member.MemberService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

/** R2 券码携带与 R3 折扣计算。 */
class RenewalCouponTest {

    private static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
    private static final Clock FIXED_CLOCK = Clock.fixed(Instant.parse("2025-12-01T00:00:00Z"), ZONE);

    private MemberService memberService;
    private RenewalRepository renewalRepository;
    private CouponRepository couponRepository;
    private SignatureVerifier signatureVerifier;
    private RenewalService renewalService;
    private Member member;

    @BeforeEach
    void setUp() {
        MemberRepository memberRepository = new MemberRepository();
        memberService = new MemberService(memberRepository, FIXED_CLOCK, ZONE);
        renewalRepository = new RenewalRepository();
        couponRepository = new CouponRepository();
        signatureVerifier = new SignatureVerifier();
        renewalService = new RenewalService(renewalRepository, memberService, couponRepository,
                signatureVerifier, FIXED_CLOCK, ZONE);
        member = memberService.register("张伟", "13800138000", LocalDateTime.parse("2026-01-15T00:00:00"));
    }

    private RenewalService.CallbackCommand command(String txnId, long originalAmountCents,
                                                   long signedAmountCents, String couponCode) {
        return new RenewalService.CallbackCommand(txnId, member.getId(), 1, originalAmountCents,
                signatureVerifier.sign(txnId, signedAmountCents), couponCode);
    }

    @Test
    void legacyCallbackWithoutCouponKeepsDefaults() {
        RenewalService.CallbackResult result = renewalService.handleCallback(command("TXN-1", 9900L, 9900L, null));

        RenewalOrder order = result.order();
        assertFalse(result.duplicate());
        assertEquals(1, renewalRepository.count());
        assertNull(order.getCouponCode());
        assertEquals(1.0, order.getDiscountRate());
        assertEquals(9900L, order.getOriginalAmountCents());
        assertEquals(9900L, order.getAmountCents());
    }

    @Test
    void blankCouponCodeIsTreatedAsNoCoupon() {
        RenewalService.CallbackResult result = renewalService.handleCallback(command("TXN-2", 9900L, 9900L, "   "));

        RenewalOrder order = result.order();
        assertNull(order.getCouponCode());
        assertEquals(9900L, order.getAmountCents());
    }

    @Test
    void validCouponChargesDiscountedPayableAmount() {
        couponRepository.save(new Coupon("SAVE20", 0.80));

        RenewalService.CallbackResult result = renewalService.handleCallback(command("TXN-3", 9900L, 7920L, "SAVE20"));

        RenewalOrder order = result.order();
        assertEquals("SAVE20", order.getCouponCode());
        assertEquals(0.80, order.getDiscountRate());
        assertEquals(7920L, order.getAmountCents());
        assertEquals(9900L, order.getOriginalAmountCents());
        assertEquals(7920L, renewalRepository.findByExternalTxnId("TXN-3").orElseThrow().getAmountCents());
    }

    @Test
    void payableAmountRoundsHalfUpToCent() {
        couponRepository.save(new Coupon("SAVE20", 0.80));

        RenewalService.CallbackResult result = renewalService.handleCallback(command("TXN-4", 9901L, 7921L, "SAVE20"));

        assertEquals(7921L, result.order().getAmountCents());
    }

    @Test
    void fullRateCouponChargesOriginalAmount() {
        couponRepository.save(new Coupon("FULL", 1.0));

        RenewalService.CallbackResult result = renewalService.handleCallback(command("TXN-5", 9900L, 9900L, "FULL"));

        assertEquals("FULL", result.order().getCouponCode());
        assertEquals(1.0, result.order().getDiscountRate());
        assertEquals(9900L, result.order().getAmountCents());
    }

    @Test
    void nonPositiveOriginalAmountIsRejectedWithoutSideEffects() {
        couponRepository.save(new Coupon("SAVE20", 0.80));
        LocalDateTime expiryBefore = memberService.getMember(member.getId()).getExpireAt();

        RenewalService.CouponException exception = assertThrows(RenewalService.CouponException.class,
                () -> renewalService.handleCallback(command("TXN-6", 0L, 0L, "SAVE20")));

        assertEquals("INVALID_AMOUNT", exception.getCode());
        assertEquals(0, renewalRepository.count());
        assertEquals(expiryBefore, memberService.getMember(member.getId()).getExpireAt());
    }

    @Test
    void signatureMustCoverPayableAmountNotOriginalAmount() {
        couponRepository.save(new Coupon("SAVE20", 0.80));

        assertThrows(RenewalService.InvalidSignatureException.class,
                () -> renewalService.handleCallback(command("TXN-7", 9900L, 9900L, "SAVE20")));
        assertEquals(0, renewalRepository.count());
    }
}

package com.acme.member.renewal;

import com.acme.member.member.Member;
import com.acme.member.member.MemberRepository;
import com.acme.member.member.MemberService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

/** R2/R3 回调接口层：状态码与响应形状。 */
class RenewalCouponControllerTest {

    private static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
    private static final Clock FIXED_CLOCK = Clock.fixed(Instant.parse("2025-12-01T00:00:00Z"), ZONE);

    private MemberService memberService;
    private RenewalRepository renewalRepository;
    private CouponRepository couponRepository;
    private SignatureVerifier signatureVerifier;
    private RenewalService renewalService;
    private RenewalController controller;
    private Member member;

    @BeforeEach
    void setUp() {
        MemberRepository memberRepository = new MemberRepository();
        memberService = new MemberService(memberRepository, FIXED_CLOCK, ZONE);
        renewalRepository = new RenewalRepository();
        couponRepository = new CouponRepository();
        signatureVerifier = new SignatureVerifier();
        renewalService = new RenewalService(renewalRepository, memberService, couponRepository,
                signatureVerifier, FIXED_CLOCK, ZONE);
        controller = new RenewalController(renewalService, renewalRepository);
        member = memberService.register("张伟", "13800138000", LocalDateTime.parse("2026-01-15T00:00:00"));
    }

    private RenewalController.CallbackRequest request(String txnId, long originalAmountCents,
                                                      long signedAmountCents, String couponCode) {
        return new RenewalController.CallbackRequest(txnId, member.getId(), 1, originalAmountCents,
                signatureVerifier.sign(txnId, signedAmountCents), couponCode);
    }

    @Test
    void legacyRequestWithoutCouponReturns200() {
        var response = controller.callback(
                new RenewalController.CallbackRequest("TXN-1", member.getId(), 1, 9900L,
                        signatureVerifier.sign("TXN-1", 9900L)));

        assertEquals(200, response.getStatusCode().value());
        assertEquals(0, response.getBody().get("code"));
        RenewalOrder order = renewalRepository.findByExternalTxnId("TXN-1").orElseThrow();
        assertNull(order.getCouponCode());
        assertEquals(1.0, order.getDiscountRate());
        assertEquals(9900L, order.getOriginalAmountCents());
        assertEquals(9900L, order.getAmountCents());
    }

    @Test
    void blankCouponCodeReturns200WithoutCoupon() {
        var response = controller.callback(request("TXN-2", 9900L, 9900L, "   "));

        assertEquals(200, response.getStatusCode().value());
        assertNull(renewalRepository.findByExternalTxnId("TXN-2").orElseThrow().getCouponCode());
    }

    @Test
    void validCouponReturns200AndStoresDiscountedOrder() {
        couponRepository.save(new Coupon("SAVE20", 0.80));

        var response = controller.callback(request("TXN-3", 9900L, 7920L, "SAVE20"));

        assertEquals(200, response.getStatusCode().value());
        RenewalOrder order = renewalRepository.findByExternalTxnId("TXN-3").orElseThrow();
        assertEquals("SAVE20", order.getCouponCode());
        assertEquals(7920L, order.getAmountCents());
    }

    @Test
    void nonPositiveAmountReturns400WithBusinessCode() {
        couponRepository.save(new Coupon("SAVE20", 0.80));
        LocalDateTime expiryBefore = memberService.getMember(member.getId()).getExpireAt();

        var response = controller.callback(request("TXN-4", 0L, 0L, "SAVE20"));

        Map<String, Object> body = response.getBody();
        assertEquals(400, response.getStatusCode().value());
        assertEquals(400, body.get("code"));
        assertEquals("INVALID_AMOUNT", body.get("error"));
        assertEquals(0, renewalRepository.count());
        assertEquals(expiryBefore, memberService.getMember(member.getId()).getExpireAt());
    }
}
